Input: {"correlation_id": "ETH-USDT-1h-1789883999999", "symbol": "ETH-USDT", "decision_time_ms": 1789889400000, "account": {"equity": "9997.63284057383", "available_margin": "9686.5196885738288", "currency": "USDT", "position_mode": "HEDGE", "as_of_ms": 1789889400000}, "position": {"position_id": "wf-main-1", "symbol": "ETH-USDT", "side": "LONG", "quantity": "0.604", "mark_price": "2575.44", "ownership_role": "MAIN", "as_of_ms": 1789889400000, "entry_price": "2578.327807", "unrealized_pnl": "-1.744235428"}, "positions": [{"position_id": "wf-main-1", "symbol": "ETH-USDT", "side": "LONG", "quantity": "0.604", "mark_price": "2575.44", "ownership_role": "MAIN", "as_of_ms": 1789889400000, "entry_price": "2578.327807", "unrealized_pnl": "-1.744235428"}], "executor_state": {"as_of_ms": 1789889400000, "controller_id": "brooks-walkforward-10d", "fills_read_status": "available", "executors": [{"executor_id": "wf-exec-1", "status": "RUNNING", "trading_pair": "ETH-USDT", "controller_id": "brooks-walkforward-10d", "position_id": "wf-main-1", "config": {"stop_price": "2569.800000000000000000000000", "target_price": "2594.609999999999999999999999"}}]}, "open_orders": [], "recent_fills": [{"fill_id": "wf-fill-1", "order_id": "wf-fill-1", "position_id": "wf-main-1", "symbol": "ETH-USDT", "side": "LONG", "status": "FILLED", "quantity": "0.604", "price": "2578.327807", "fee": "0.6229239981712", "filled_at_ms": 1789884959999}], "fills_since_last_event": [], "original_trade_intent": {"schema": "brooks.trade-intent.v2", "role": "TRADER", "decision": "ENTER_LONG", "symbol": "ETH-USDT", "decision_time_ms": 1789883999999, "market_context": {"regime": "H4 bull-trend (channel) with an unconfirmed reversal candidate; M15/H1 in a tight 12-bar range at the low of a strong bear breakout", "h4_context": "current, as-of 1789876799999: primary_regime bull-trend, phase channel, always_in long (medium relevance); bars 111-112 broke out with closes near highs (2578.60 of 2585.50; 2636.28 of 2643.52) an